create or replace function private.sync_fixed_cost_transactions_final() returns trigger language plpgsql security definer set search_path='' as $$ declare i int;v_date date;v_month int;v_period text;v_paid boolean;begin if tg_op in ('UPDATE','DELETE') then delete from public.transactions where household_id=old.household_id and source_type='FIXED_COST' and source_id=old.id;end if;if tg_op<>'DELETE' then for i in 0..23 loop v_date:=(date_trunc('month',current_date)::date+make_interval(months=>i))::date;v_month:=extract(month from v_date)::int;if coalesce(new.months[v_month],false) then v_date:=make_date(extract(year from v_date)::int,v_month,least(greatest(new.due_day,1),extract(day from(date_trunc('month',v_date)+interval '1 month - 1 day'))::int));v_period:=to_char(v_date,'YYYY-MM');select paid into v_paid from public.fixed_cost_payments where household_id=new.household_id and fixed_cost_id=new.id and period=v_period limit 1;insert into public.transactions(household_id,date,description,amount,type,category,pay_method,card_name,responsible,is_fixed,paid,payment_method_name,payment_method_id,card_id,source_type,source_id,source_index,source_total,source_period) values(new.household_id,v_date,new.name,new.amount,'DESPESA',new.category,new.pay_method,new.card_name,new.responsible,true,coalesce(v_paid,false),new.payment_method_name,new.payment_method_id,new.card_id,'FIXED_COST',new.id,i+1,24,v_period) on conflict (household_id,source_type,source_id,source_index) where source_type is not null and source_id is not null and source_index is not null do update set date=excluded.date,description=excluded.description,amount=excluded.amount,category=excluded.category,pay_method=excluded.pay_method,card_name=excluded.card_name,responsible=excluded.responsible,paid=excluded.paid,payment_method_name=excluded.payment_method_name,payment_method_id=excluded.payment_method_id,card_id=excluded.card_id,source_total=excluded.source_total,source_period=excluded.source_period;end if;end loop;end if;return coalesce(new,old);end $$;
